  // Casos com total terminando em zero (formato de duas casas)
  { peso_kg: 5,    uf_origem: 'SP', uf_destino: 'SP', volumes: 5,  valor_base: 25,  multiplicador: 1.0, desconto: 0,    valor_total_esperado: '28.00' },
  { peso_kg: 5,    uf_origem: 'SP', uf_destino: 'SP', volumes: 11, valor_base: 25,  multiplicador: 1.0, desconto: 0.05, valor_total_esperado: '26.60' }
];

function rodarCaso(index) {
  if (index >= casos.length) {
    return;
  }

  const caso = casos[index];
  const rotulo = `${caso.peso_kg}kg ${caso.uf_origem}→${caso.uf_destino} ${caso.volumes}vol`;
  const body = {
    cliente: `Arredondamento ${rotulo}`,
    peso_kg: caso.peso_kg,
    volumes: caso.volumes,
    uf_origem: caso.uf_origem,
    uf_destino: caso.uf_destino
  };

  pm.sendRequest({
    url: `${pm.environment.get("url_base_v2")}/api/cotacoes`,
    method: 'POST',
    header: { 'Content-Type': 'application/json' },
    body: { mode: 'raw', raw: JSON.stringify(body) }
  }, function (err, resV2) {
    if (err) { console.error("Erro:", err); return rodarCaso(index + 1); }

    const json = resV2.json();

    // Texto cru do valor_total, do jeito que a API mandou (sem o parse do JSON)
    const textoCru = resV2.text();
    const totalCru = (textoCru.match(/"valor_total"\s*:\s*"?(-?\d+(?:\.\d+)?)"?/) || [])[1];

    // Premissas: se alguma falhar, o problema NÃO é arredondamento
    pm.test(`[${rotulo}] premissa - valor_base ${caso.valor_base}`, function () {
      pm.expect(json.valor_base).to.eql(caso.valor_base);
    });

    pm.test(`[${rotulo}] premissa - multiplicador ${caso.multiplicador}`, function () {
      pm.expect(json.multiplicador).to.eql(caso.multiplicador);
    });

    pm.test(`[${rotulo}] premissa - desconto ${caso.desconto}`, function () {
      pm.expect(json.desconto).to.eql(caso.desconto);
    });

    // Regra 1: o valor está arredondado corretamente (compara o número)
    pm.test(`[${rotulo}] arredondamento - valor_total ${caso.valor_total_esperado}`, function () {
      pm.expect(json.valor_total).to.eql(Number(caso.valor_total_esperado));
    });

    // Regra 2: o valor vem com exatamente duas casas decimais (compara o texto)
    pm.test(`[${rotulo}] formato - duas casas decimais, esperado ${caso.valor_total_esperado} (veio: ${totalCru})`, function () {
      pm.expect(String(totalCru)).to.eql(caso.valor_total_esperado);
    });

    rodarCaso(index + 1);
  });
}

