const url = pm.request.url.toString();

const camposObrigatorios = [
    "cliente",
    "peso_kg",
    "volumes",
    "uf_origem",
    "uf_destino"
];

const payloadValido = {
    cliente: "Teste QA",
    peso_kg: 10,
    volumes: 1,
    uf_origem: "SP",
    uf_destino: "RJ"
};

camposObrigatorios.forEach(function (campo) {

    const payloadInvalido = { ...payloadValido };

    delete payloadInvalido[campo];

    pm.sendRequest({
        url: url,
        method: "POST",
        header: {
            "Content-Type": "application/json"
        },
        body: {
            mode: "raw",
            raw: JSON.stringify(payloadInvalido)
        }
    }, function (err, response) {

        pm.test(`Campo obrigatório ausente: ${campo}`, function () {

            pm.expect(err).to.equal(null);

            pm.expect(response.code).to.equal(422);

            pm.expect(response.headers
                .get("Content-Type"))
                .to.include("application/json");

            const body = response.json();

            pm.expect(body).to.have.property("erro");

            pm.expect(body.erro)
                .to.be.a("string")
                .and.not.empty;
        });
    });
});

const url = pm.request.url.toString();

const payloadBase = {
    cliente: "Teste QA",
    peso_kg: 10,
    volumes: 1,
    uf_origem: "SP",
    uf_destino: "RJ"
};

const cenarios = [
    {
        nome: "peso igual a zero",
        peso: 0,
        statusEsperado: 422
    },
    {
        nome: "peso negativo",
        peso: -1,
        statusEsperado: 422
    },
    {
        nome: "menor peso positivo",
        peso: 0.01,
        statusEsperado: 201
    }
];

cenarios.forEach(function (cenario) {

    const payload = {
        ...payloadBase,
        peso_kg: cenario.peso
    };

    pm.sendRequest({
        url: url,
        method: "POST",
        header: {
            "Content-Type": "application/json"
        },
        body: {
            mode: "raw",
            raw: JSON.stringify(payload)
        }
    }, function (err, response) {

        pm.test(
            `Peso ${cenario.nome} (${cenario.peso})`,
            function () {

                pm.expect(err).to.equal(null);

                pm.expect(response.code)
                    .to.equal(cenario.statusEsperado);

                pm.expect(response.headers
                    .get("Content-Type"))
                    .to.include("application/json");

                const body = response.json();

                if (cenario.statusEsperado === 422) {

                    pm.expect(body)
                        .to.have.property("erro");

                    pm.expect(body.erro)
                        .to.be.a("string")
                        .and.not.empty;

                } else {

                    pm.expect(body)
                        .to.have.property("id");

                    pm.expect(body.id)
                        .to.be.a("number");

                    pm.expect(body.peso_kg)
                        .to.equal(cenario.peso);
                }
            }
        );
    });
});
